function longestWalk(root: TreeNode | null): number {
  const height = (n: TreeNode | null): number => n ? 1 + Math.max(height(n.left), height(n.right)) : 0;
  let best = 0;
  const visit = (n: TreeNode | null): void => {
    if (!n) return;
    best = Math.max(best, height(n.left) + height(n.right));
    visit(n.left);
    visit(n.right);
  };
  visit(root);
  return best;
}

