class Solution:
    def longestWalk(self, root: Optional[TreeNode]) -> int:
        def height(n):
            return 1 + max(height(n.left), height(n.right)) if n else 0

        best = 0
        stack = [root]
        while stack:
            n = stack.pop()
            if n:
                best = max(best, height(n.left) + height(n.right))
                stack.extend((n.left, n.right))
        return best

