function longestWalk(root: TreeNode | null): number {
  let best = 0;
  const height = (n: TreeNode | null): number => {
    if (!n) return 0;
    const l = height(n.left), r = height(n.right);
    best = Math.max(best, l + r); // walk that bends here
    return 1 + Math.max(l, r);    // what the parent can extend
  };
  height(root);
  return best;
}

